custom_function.script:
function decodeExecute(hex_string) {
    if (hex_string === null || hex_string === undefined) {
        return null;
    }
    if (typeof hex_string !== 'string') {
        hex_string = String(hex_string);
    }
    if (hex_string.length === 0) {
        return '';
    }
    var MAX_INPUT_LEN = 131072;
    var hex = hex_string.replace(/[\s]/g, '');
    if (hex.length >= 2 && hex.charAt(0) === '0' &&
        (hex.charAt(1) === 'x' || hex.charAt(1) === 'X')) {
        hex = hex.substring(2);
    }
    if (hex.length === 0) {
        return '';
    }
    if (hex.length > MAX_INPUT_LEN) {
        hex = hex.substring(0, MAX_INPUT_LEN);
    }
    if (hex.length % 2 !== 0) {
        return null;
    }
    var result = [];
    for (var i = 0; i < hex.length; i += 2) {
        var hi = hex.charCodeAt(i);
        var lo = hex.charCodeAt(i + 1);
        var hiVal, loVal;
        if (hi >= 48 && hi <= 57)       hiVal = hi - 48;
        else if (hi >= 65 && hi <= 70)  hiVal = hi - 55;
        else if (hi >= 97 && hi <= 102) hiVal = hi - 87;
        else return null;
        if (lo >= 48 && lo <= 57)       loVal = lo - 48;
        else if (lo >= 65 && lo <= 70)  loVal = lo - 55;
        else if (lo >= 97 && lo <= 102) loVal = lo - 87;
        else return null;
        result.push(String.fromCharCode((hiVal << 4) | loVal));
    }
    return result.join('');
}

function encodeExecute(plain_string) {
    if (plain_string === null || plain_string === undefined) {
        return null;
    }
    if (typeof plain_string !== 'string') {
        plain_string = String(plain_string);
    }
    if (plain_string.length === 0) {
        return '';
    }
    var MAX_INPUT_LEN = 65536;
    var HEX_CHARS = '0123456789ABCDEF';
    var src = plain_string;
    if (src.length > MAX_INPUT_LEN) {
        src = src.substring(0, MAX_INPUT_LEN);
    }
    var result = [];
    for (var i = 0; i < src.length; i++) {
        var code = src.charCodeAt(i);
        if (code <= 255) {
            result.push(HEX_CHARS.charAt((code >> 4) & 0x0F));
            result.push(HEX_CHARS.charAt(code & 0x0F));
        } else {
            result.push(HEX_CHARS.charAt((code >> 12) & 0x0F));
            result.push(HEX_CHARS.charAt((code >> 8) & 0x0F));
            result.push(HEX_CHARS.charAt((code >> 4) & 0x0F));
            result.push(HEX_CHARS.charAt(code & 0x0F));
        }
    }
    return result.join('');
}
